import numpy as np
# Inverse/forward poses with explicit angles. base at (238,15), l1=92,l2=94. Find angles for wrist positions by solving 2link angles in image coords.
# x=base+l1*cos(a)+l2*cos(a+b), y=base+l1*sin(a)+l2*sin(a+b). brute a,b
base=np.array([238.,15.]);L=[92,94]
def f(a,b):return base+np.array([L[0]*np.cos(a)+L[1]*np.cos(a+b),L[0]*np.sin(a)+L[1]*np.sin(a+b)])
for t in [(171,110),(129,113),(126,90),(115,87),(75,99),(54,121),(66,117)]:
 best=None
 for a in np.linspace(-np.pi,np.pi,1441):
  for b in np.linspace(-2.8,2.8,1121):
   p=f(a,b);d=np.linalg.norm(p-t)
   if best is None or d<best[0]:best=(d,a,b,p)
 print(t,'best',best[0],np.degrees(best[1]),np.degrees(best[2]),best[3])
PY"
